{
  switch(union_selection) {
  case ALT_b1:
    {TTCN_Buffer buf;
    encode_oer_tag(*S1_b1_descr_.ber, p_buf);
    field_b1->OER_encode(S1_b1_descr_, buf);
    p_buf.put_buf(buf);
    break;
}  case ALT_b2:
    {TTCN_Buffer buf;
    encode_oer_tag(*S1_b2_descr_.ber, p_buf);
    field_b2->OER_encode(S1_b2_descr_, buf);
    encode_oer_length(buf.get_len(), p_buf, FALSE);
    p_buf.put_buf(buf);
    break;
}  case ALT_b3:
    {TTCN_Buffer buf;
    encode_oer_tag(*S1_b3_descr_.ber, p_buf);
    field_b3->OER_encode(S1_b3_descr_, buf);
    encode_oer_length(buf.get_len(), p_buf, FALSE);
    p_buf.put_buf(buf);
    break;
}  default:
    TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, 
      "Encoding an unbound value of type @Foo.S1.");
    return -1;
  }

  return 0;
}
int S1::OER_decode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, OER_struct& p_oer)
{
  const ASN_Tag_t& descr = decode_oer_tag(p_buf);
  if (S1_b1_descr_.ber->tags[S1_b1_descr_.ber->n_tags-1].tagclass == descr.tagclass &&
      S1_b1_descr_.ber->tags[S1_b1_descr_.ber->n_tags-1].tagnumber == descr.tagnumber) {
    b1().OER_decode(S1_b1_descr_, p_buf, p_oer);
  } else 
  if (S1_b2_descr_.ber->tags[S1_b2_descr_.ber->n_tags-1].tagclass == descr.tagclass &&
      S1_b2_descr_.ber->tags[S1_b2_descr_.ber->n_tags-1].tagnumber == descr.tagnumber) {
      decode_oer_length(p_buf, FALSE);
    b2().OER_decode(S1_b2_descr_, p_buf, p_oer);
  } else 
  if (S1_b3_descr_.ber->tags[S1_b3_descr_.ber->n_tags-1].tagclass == descr.tagclass &&
      S1_b3_descr_.ber->tags[S1_b3_descr_.ber->n_tags-1].tagnumber == descr.tagnumber) {
      decode_oer_length(p_buf, FALSE);
    b3().OER_decode(S1_b3_descr_, p_buf, p_oer);
  } else 
{
    TTCN_error("Cannot find matching tag for type S1");
}
  return 0;
}
void S1::PER_encode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, int p_options) const
{
if (!is_bound()) {
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Encoding an unbound CHOICE value.");
return;
}
boolean ext_bit = union_selection > 1;
p_buf.PER_put_bit(ext_bit);
if (ext_bit) {
INTEGER sel_code;
TTCN_Buffer ext_add_buf;
switch (union_selection) {
case ALT_b2: {
sel_code = 0;
field_b2->PER_encode(S1_b2_descr_, ext_add_buf, p_options);
break; }
case ALT_b3: {
sel_code = 1;
field_b3->PER_encode(S1_b3_descr_, ext_add_buf, p_options);
break; }
default:
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Internal error: Invalid CHOICE selection, expected an extension addition field.");
return;
}
sel_code.PER_encode_normally_small(p_buf, p_options);
PER_encode_opentype(p_buf, ext_add_buf, p_options);
}
else switch (union_selection) {
case ALT_b1: {
field_b1->PER_encode(S1_b1_descr_, p_buf, p_options);
break; }
default:
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Internal error: Invalid CHOICE selection, expected an extension root field.");
break;
}
}

void S1::PER_decode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
boolean ext_bit = p_buf.PER_get_bit();
if (ext_bit) {
INTEGER sel_code;
sel_code.PER_decode_normally_small(p_buf, p_options);
int sel_int = sel_code;
switch (sel_int) {
case 0: {
TTCN_Buffer ext_add_buf;
PER_decode_opentype(p_buf, ext_add_buf, p_options);
b2().PER_decode(S1_b2_descr_, ext_add_buf, p_options);
break; }
case 1: {
TTCN_Buffer ext_add_buf;
PER_decode_opentype(p_buf, ext_add_buf, p_options);
b3().PER_decode(S1_b3_descr_, ext_add_buf, p_options);
break; }
default:
PER_skip_opentype(p_buf, p_options);
break;
}
} else {
b1().PER_decode(S1_b1_descr_, p_buf, p_options);
}
}


